fn extraction_argument_long(rest: &[u8], width: usize) -> Option<(u64, &[u8])> {
	if width > rest.len() { return None; }
	let (encoded, rest) = rest.split_at(width);
	let value = extraction_argument_word(encoded, width);
	Some((value,rest))
}

fn extraction_argument_word(encoded: &[u8], width: usize) -> u64 {
	let mut word = [0; 8];
	word[8 - width..].copy_from_slice(encoded);
	u64::from_be_bytes(word)
}

fn extraction_preflight_field(remaining: &[u8], major: u8) -> Option<&[u8]> {
		let (argument, rest) = primitive_argument(remaining, major)?;
		let remaining = if major == 2 {
			rest.get(usize::try_from(argument).ok()?..)?
		} else {
			rest
		};
Some(remaining)
}

fn extraction_strip_prefix<'a>(input: &'a [u8], prefix: &[u8]) -> Option<&'a [u8]> {

        // This function will need rewriting if and when SlicePattern becomes more sophisticated.

        let n = prefix.len();
        if n <= input.len() {
            let (head, tail) = input.split_at(n);
            if head == prefix {
                return Some(tail);
            }
        }
        None

}

